import openpyxl
out=openpyxl.load_workbook('task/output.xlsx')
ws2=out['Sheet2']
def P(m,r):
    return f'ISNUMBER(SEARCH("{m}",$A{r}&""))'
P_expr={}
for m in range(10):
    P_expr[m]=P(m,'r')
C_expr={}
cum=[]
for m in range(10):
    cum.append(P_expr[m])
    C_expr[m]='+'.join(cum)
C_tot='+'.join(P_expr[m] for m in range(10))

for r in range(2,9):
    # substitute r
    def sub(s): return s.replace('r',str(r))
    for k in range(1,6):
        col=2+k
        inner='"'
        for m in range(9,-1,-1):
            inner=f'IF({sub(C_expr[m])}>={k},{m},{inner})'
        formula=f'=IF(({sub(C_tot)})<{k},"",{inner})'
        ws2.cell(r,col).value=formula
out.save('task/output.xlsx')
print("done")
print(ws2.cell(2,3).value[:100])
EOF
